function approvalAllows(snapshot) {
  const outside = snapshot?.sale_origin === 'outside_system' || snapshot?.sale_context === 'out_of_area_phone';
  return !outside || String(snapshot?.admin_approval?.status || '').toLowerCase() === 'approved';
}

export function isPayEligible(sale) {
  return sale?.verification_status === 'verified_processed' &&
    sale?.competition_eligible === true &&
    sale?.sale_status !== 'cancelled' &&
    approvalAllows(sale?.compensation_snapshot || {});
}

export function startOfWeekPacific(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Los_Angeles', year: 'numeric', month: '2-digit', day: '2-digit', weekday: 'short'
  }).formatToParts(date);
  const get = type => parts.find(part => part.type === type)?.value || '';
  const dayIndex = {Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6}[get('weekday')];
  const noonUtc = new Date(Date.UTC(Number(get('year')), Number(get('month')) - 1, Number(get('day')), 12));
  noonUtc.setUTCDate(noonUtc.getUTCDate() - ((dayIndex + 6) % 7));
  const monday = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Los_Angeles', year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(noonUtc);
  return monday;
}

function needsInternetBase(sale) {
  return sale?.isp === 'Quantum' || sale?.isp === 'Brightspeed' ||
    (sale?.isp === 'AT&T' && ['Fiber', 'Internet Air'].includes(String(sale?.internet_product || '')));
}

export function annotateEarnedPay(records, rule) {
  const counts = new Map();
  for (const sale of records || []) {
    if (!isPayEligible(sale)) continue;
    const key = `${sale.rep_user_id}|${startOfWeekPacific(sale.created_at)}`;
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  const increases = new Map();
  for (const [key, count] of counts) {
    increases.set(key, Number(weeklyProductionTier(rule, count).current?.increase_per_sale || 0));
  }
  return (records || []).map(sale => {
    const snapshot = sale.compensation_snapshot || {};
    const base = snapshot.base_commission == null ? null : Number(snapshot.base_commission);
    const mobile = Number(snapshot.att_mobile_originating_commission || 0);
    const priced = (!needsInternetBase(sale) || (base != null && Number.isFinite(base))) && Number.isFinite(mobile);
    const eligible = isPayEligible(sale);
    const key = `${sale.rep_user_id}|${startOfWeekPacific(sale.created_at)}`;
    const increase = eligible ? Number(increases.get(key) || 0) : 0;
    const scheduled = (base != null && Number.isFinite(base) ? base : 0) + (Number.isFinite(mobile) ? mobile : 0);
    const cancelled = sale.sale_status === 'cancelled';
    let payStatus = 'not_eligible';
    const paidAmount = Number(sale.commission_paid_amount || 0);
    if (cancelled) payStatus = paidAmount > 0 ? 'cancelled_paid_chargeback' : 'cancelled_unpaid_no_chargeback';
    else if (!eligible) payStatus = String(sale.verification_status || 'pending_verification');
    else if (!priced) payStatus = 'accounting_review_required';
    else payStatus = 'earned';
    return {
      ...sale,
      commission_pay_level: snapshot.pay_level || snapshot.classification || null,
      base_commission: base,
      att_mobile_originating_commission: Number.isFinite(mobile) ? mobile : 0,
      weekly_production_increase_per_sale: increase,
      current_earned_pay: eligible && priced ? scheduled + increase : 0,
      cancellation_reduction: cancelled && paidAmount > 0 ? Number(sale.commission_chargeback_amount || paidAmount) : 0,
      pay_status: payStatus,
      compensation_rule_source: snapshot.source || null
    };
  });
}

function auditValue(row, column) {
  if (column === 'order_date') return row.created_at;
  return row[column];
}

export function csvCell(value) {
  let text = value == null ? '' : typeof value === 'object' ? JSON.stringify(value) : String(value);
  if (/^[\t\r\n ]*[=+\-@]/.test(text)) text = `'${text}`;
  return `"${text.replaceAll('"', '""')}"`;
}

export function buildAccountingCsv(records) {
  return [
    ACCOUNTING_COLUMNS.join(','),
    ...(records || []).map(row => ACCOUNTING_COLUMNS.map(column => csvCell(auditValue(row, column))).join(','))
  ].join('\n');
}

export function isCancelledProviderStatus(value) {
  const normalized = String(value || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  return new Set([
    'cancelled','canceled','void','voided','chargeback','charged_back','disconnected','disconnect',
    'rescinded','reversed','returned','failed_install','install_cancelled','install_canceled'
  ]).has(normalized);
}

export const PAY_LEVELS = Object.freeze([
  Object.freeze({ key: 'trainee', label: 'Trainee' }),
  Object.freeze({ key: 'experienced', label: 'Experienced Rep' }),
  Object.freeze({ key: 'active_manager_trainer', label: 'Active Manager / Trainer' })
]);

const PAY_LEVEL_KEYS = new Set(PAY_LEVELS.map(level => level.key));

export function normalizePayLevel(value) {
  const key = String(value || '').trim().toLowerCase();
  return PAY_LEVEL_KEYS.has(key) ? key : null;
}

export function payLevelLabel(value) {
  const key = normalizePayLevel(value);
  return PAY_LEVELS.find(level => level.key === key)?.label || 'Not assigned';
}

function numeric(value) {
  const amount = Number(value);
  return Number.isFinite(amount) ? amount : null;
}

export function baseCommissionForSale(rule, sale, payLevel) {
  const level = normalizePayLevel(payLevel);
  if (!level) return null;
  const provider = String(sale?.isp || '').trim();
  const product = String(sale?.internet_product || '').trim();
  const speed = Math.max(0, Math.round(Number(sale?.internet_speed_mbps || 0)));

  if (provider === 'Quantum') return numeric(rule?.quantum?.[level]);
  if (provider === 'Brightspeed') {
    const tier = speed >= 2000 ? '2_gig' : speed >= 1000 ? '1_gig' : 'below_1_gig';
    return numeric(rule?.brightspeed?.[tier]?.[level]);
  }
  if (provider === 'AT&T') {
    if (product === 'Internet Air') return numeric(rule?.att?.internet_air);
    if (product === 'Fiber') {
      const tier = speed >= 1000 ? 'fiber_1_gig' : 'fiber_below_1_gig';
      return numeric(rule?.att?.[tier]?.[level]);
    }
  }
  return null;
}

export function attMobileCommission(rule, lineCount) {
  const lines = Math.max(0, Math.min(20, Math.round(Number(lineCount || 0))));
  if (!lines) return 0;
  const first = Number(rule?.att?.mobile_first_line || 0);
  const additional = Number(rule?.att?.mobile_additional_line || 0);
  return first + Math.max(0, lines - 1) * additional;
}

export function weeklyProductionTier(rule, saleCount) {
  const count = Math.max(0, Math.round(Number(saleCount || 0)));
  const tiers = Array.isArray(rule?.weekly_production_pay_increase)
    ? rule.weekly_production_pay_increase
        .map(tier => ({
          min_sales: Math.max(0, Math.round(Number(tier?.min_sales || 0))),
          max_sales: tier?.max_sales == null ? null : Math.max(0, Math.round(Number(tier.max_sales))),
          increase_per_sale: Math.max(0, Number(tier?.increase_per_sale || 0))
        }))
        .filter(tier => tier.min_sales > 0)
        .sort((left, right) => left.min_sales - right.min_sales)
    : [];
  let current = null;
  let next = null;
  for (const tier of tiers) {
    if (count >= tier.min_sales) current = tier;
    else if (!next) next = tier;
  }
  return { tiers, current, next };
}

export function commissionSnapshot(rule, sale, payLevel) {
  const level = normalizePayLevel(payLevel);
  const lines = Math.max(0, Math.min(20, Math.round(Number(sale?.mobile_phone_lines ?? sale?.att_mobile_lines ?? 0))));
  return {
    pay_level: level,
    pay_level_label: payLevelLabel(level),
    base_commission: baseCommissionForSale(rule, sale, level),
    att_mobile_originating_commission: attMobileCommission(rule, lines),
    mobile_phone_lines: lines
  };
}

